def solution(input_str):
    import sys

    def solve():
        data = input_str.strip().split('\n')
        idx = 0

        if idx >= len(data):
            return ""

        t = int(data[idx].strip())
        idx += 1

        results = []

        for _ in range(t):
            while idx < len(data) and not data[idx].strip():
                idx += 1
            if idx >= len(data):
                break

            nm = data[idx].strip().split()
            idx += 1
            n, m = int(nm[0]), int(nm[1])

            matrix = []
            for _ in range(n):
                while idx < len(data) and not data[idx].strip():
                    idx += 1
                row = list(map(int, data[idx].strip().split()))
                idx += 1
                matrix.append(row)

            xor_sum = 0
            for i in range(n):
                for j in range(m):
                    xor_sum ^= matrix[i][j]

            if xor_sum != 0:
                results.append("Ashish")
            else:
                results.append("Jeel")

        return "\n".join(results)

    return solve()

