def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())

    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    # Function to check if it's possible to keep all bamboos <= target height
    def check(target):
        if target < 0:
            return False

        total_hits_needed = 0
        for h, a in bamboos:
            final_height = h + a * m  # Height after m days without any hits
            if final_height > target:
                hits_needed = (final_height - target + p - 1) // p  # ceil division
                total_hits_needed += hits_needed

            if total_hits_needed > k * m:
                return False

        return total_hits_needed <= k * m

    # Binary search for the minimum possible maximum height
    # Lower bound: 0, Upper bound: max possible height without any hits
    low = 0
    high = 0
    for h, a in bamboos:
        high = max(high, h + a * m)

    result = high

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(result)

def solution(grid_input):
    lines = grid_input.strip().split('\n')
    n, m = map(int, lines[0].split())
    for i in range(1, n + 1):
        if len(lines[i-1]) == 0:
            lines[i-1] = ' ' * m

    grid = [list(row) for row in lines]

    def get_rooms():
        rooms = []
        visited = [[False] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.' and not visited[i][j]:
                    room = []
                    stack = [(i, j)]
                    visited[i][j] = True
                    while stack:
                        x, y = stack.pop()
                        room.append((x, y))
                        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < n and 0 <= ny < m:
                                if grid[nx][ny] == '.' and not visited[nx][ny]:
                                    visited[nx][ny] = True
                                    stack.append((nx, ny))
                    rooms.append(room)
        return rooms

    def is_rectangle(room):
        if not room:
            return True
        min_r = min(r for r, c in room)
        max_r = max(r for r, c in room)
        min_c = min(c for r, c in room)
        max_c = max(c for r, c in room)
        width = max_c - min_c + 1
        height = max_r - min_r + 1
        expected_cells = width * height
        actual_cells = len(room)
        return expected_cells == actual_cells

    removed = 0
    changed = True

    while changed and removed < n * m:
        changed = False
        rooms = get_rooms()
        removed_count = 0
        wall_removed_positions = []

        for room in rooms:
            if not is_rectangle(room):
                min_r = min(r for r, c in room)
                max_r = max(r for r, c in room)
                min_c = min(c for r, c in room)
                max_c = max(c for r, c in room)

                rectangle_cells = set()
                for r in range(min_r, max_r + 1):
                    for c in range(min_c, max_c + 1):
                        rectangle_cells.add((r, c))

                outside_cells = set(room) - rectangle_cells

                if outside_cells:
                    sort_key = lambda x: len([y_x, y_y for y_x, y_y in room if y_x == x[0] or y_y == x[1]])
                    sorted_outside = sorted(outside_cells, key=lambda x: (x[0], x[1]))

                    found = False
                    for x, y in sorted_outside:
                        if grid[x][y] == '*':
                            if (x, y) not in wall_removed_positions and x > min_r or y > min_c:
                                grid[x][y] = '.'
                                changed = True
                                wall_removed_positions.append((x, y))
                                removed_count += 1
                                found = True
                                break

                    if not found:
                        for x, y in sorted_outside:
                            if grid[x][y] == '*':
                                grid[x][y] = '.'
                                changed = True
                                wall_removed_positions.append((x, y))
                                removed_count += 1
                                break

        if not changed and removed_count == 0:
            break

    for i in range(n):
        output_lines.append(''.join(grid[i]))
    return '\n'.join(output_lines)

