        return False

    # Compute common ratio from first two elements
    # arr[i] = arr[0] * r^i
    # So arr[i] * arr[0] = arr[i+1] * arr[i-1] (cross-product to avoid division)
    # i.e., arr[i+1] * arr[i-1] should equal arr[i]^2

    for i in range(1, n - 1):
        left = arr[i+1] * arr[i-1]
        right = arr[i] * arr[i]
        if left != right:
            return False

    return True


