    for line in lines[1:m+1]:
        parts = line.split()
        if len(parts) >= 2:
            v, u = int(parts[0]), int(parts[1])
            graph[v].append(u)
            graph[u].append(v)

    # Try to find k cycles first
    cycles = []
    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)

    def dfs_find_cycles(u, p):
        visited[u] = True
        for v in graph[u]:
            if v == p:
                continue
            if visited[v] and v != p and len(visited) > 1:
                # Found cycle - backtrack to find it
                idx = 0
                curr = u
                path = []
                while True:
                    path.append(curr)
                    curr = parent[curr]
                    if curr == v:
                        break
                if len(path) >= 3:
                    if len(path) % 3 != 0:
                        cycles.append(path[:])
            else:
                if not visited[v]:
                    parent[v] = u
                    dfs_find_cycles(v, u)

    for start in range(1, n + 1):
        if not visited[start]:
            parent[start] = -1
            new_parent = [-1] * (n + 1)
            visited[:] = [False] * (n + 1)

            def find_cycles_stack(u, p):
                stack = [(u, True)]
                while stack:
                    curr, visited_check = stack.pop()
                    if visited_check:
                        visited[curr] = True
                        for v in graph[curr]:
                            if v == p:
                                continue
                            if visited[v] and v != p:
                                # Extract cycle
                                path = []
                                node = curr
                                while node != v:
                                    path.append(node)
                                    node = new_parent[node]
                                path.append(v)
                                path.reverse()
                                if len(path) >= 3 and len(path) % 3 != 0:
                                    cycles.append(path[:])
                            elif not visited[v]:
                                new_parent[v] = curr
                                stack.append((v, True))
                        stack.append((curr, False))
                    else:
                        if len(cycles) >= k:
                            break

            find_cycles_stack(start, -1)
            if len(cycles) >= k:
                break

    if len(cycles) >= k:
        result = ["CYCLES"]
        for cycle in cycles[:k]:
            result.append(str(len(cycle)))
            result.append(" ".join(map(str, cycle)))
        return "\n".join(result)

