            if start == target:
                continue
            fill_parent = [-1] * (n + 1)
            if find_path_dfs(start, target):
                path_list = []
                curr = target
                while curr != start:
                    path_list.append(curr)
                    curr = fill_parent[curr]
                path_list.append(start)
                path_list.reverse()
                if len(path_list) >= n // k:
                    result = ["PATH", str(len(path_list)), " ".join(map(str, path_list))]
                    return "\n".join(result)
                break

