import math
import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n = int(lines[0])
    centers = []
    for i in range(1, n + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 2:
            x, y = float(parts[0]), float(parts[1])
            centers.append((x, y))

    if len(centers) == 1:
        return "-1\n"

    if len(centers) < 2:
        return "-1\n"

    # Check if all circles are collinear (no hole can be formed)
    if len(centers) >= 2:
        x1, y1 = centers[0]
        x2, y2 = centers[1]

        if abs(x2 - x1) > 1e-9:  # Not vertical line
            m = (y2 - y1) / (x2 - x1)
            for i in range(2, len(centers)):
                x, y = centers[i]
                if abs(y - y1 - m * (x - x1)) > 1e-6:
                    break
            else:
                # All points are collinear
                return "-1\n"
        else:  # Vertical line
            for i in range(2, len(centers)):
                x, y = centers[i]
                if abs(x - x1) > 1e-6:
                    break
            else:
                return "-1\n"

    # Compute maximum distance between any two centers
    max_dist = 0.0
    for i in range(len(centers)):
        for j in range(i + 1, len(centers)):
            dx = centers[i][0] - centers[j][0]
            dy = centers[i][1] - centers[j][1]
            dist = math.sqrt(dx*dx + dy*dy)
            max_dist = max(max_dist, dist)

    if max_dist == 0:
        return "-1\n"

    # Binary search for the time when the last hole disappears
    low = 0.0
    high = max_dist
    ans = high

    def has_hole_at_time(t):
        """Check if there exists any hole at time t (radius = t).
        A hole exists if there are overlapping circles that form an enclosure.
        """
        # Build graph where edges connect circles that overlap
        adj = [[] for _ in range(len(centers))]
        for i in range(len(centers)):
            for j in range(i + 1, len(centers)):
                dx = centers[i][0] - centers[j][0]
                dy = centers[i][1] - centers[j][1]
                dist = math.sqrt(dx*dx + dy*dy)
                # Two circles overlap (radius=t) if distance < 2*t
                if dist < 2 * t - 1e-10:
                    adj[i].append(j)
                    adj[j].append(i)

        # Check for cycles in the overlap graph that could enclose a region
        # A hole exists if there's a cycle of at least 3 overlapping circles
        for start in range(len(centers)):
            visited = set()
            path = []

            def dfs(node, path_set):
                if node in path_set:
                    # Found cycle
                    return len(path) >= 3
                if node in visited:
                    return False

                visited.add(node)
                path.append(node)
                path_set.add(node)

                for neighbor in adj[node]:
                    if dfs(neighbor, path_set):
                        return True

                path.pop()
                path_set.remove(node)
                return False

            dfs(start, set())

        return False

    # Binary search
    for _ in range(80):
        mid = (low + high) / 2
        if has_hole_at_time(mid):
            low = mid
            ans = max(ans, mid)
        else:
            high = mid
            ans = min(ans, mid)

    # The answer is the time when holes disappear
    # Binary search should converge to a clean boundary
    return f"{ans:.6f}\n"


