    # Calculate sum of squared distances for n points
    def calculate_max_distance(index_set):
        soma_quad = 0
        p = [points[i] for i in index_set]
        # Sum of squared distances between all pairs
        for i in range(n):
            for j in range(i + 1, n):
                dx = p[i][0] - p[j][0]
                dy = p[i][1] - p[j][1]
                soma_quad += dx * dx + dy * dy
        return soma_quad, p

    max_sum = -1
    soln = []

    # Try all combinations of n points (note: points can be at same coordinate)
    # Since n is small (2 <= n <= 8), we can use product
    for p_prod in itertools.product(points, repeat=n):
        current_sum, p = calculate_max_distance(range(n))
        if current_sum > max_sum:
            max_sum = current_sum
            soln = p

    output_lines = [str(max_sum)]
    for p in soln:
        output_lines.append(f"{p[0]} {p[1]}")

