def solution(input_str):
    parts = input_str.strip().split()
    a = int(parts[0])
    b = int(parts[1])
    n = int(parts[2])

    # If a == 1, then 1^b = 1 for all b, which is always < n (since n >= 2)
    # Players can increase b indefinitely without ever reaching n, causing a draw
    if a == 1:
        return "Missing\n\n"

    # Memoization for game theory DP
    memo = {}
    visited = set()

    def is_losing(a, b):
        """Returns True if current player loses from position (a, b)"""
        key = (a, b)
        if key in memo:
            return memo[key]
        if key in visited:
            return False  # Should not happen due to monotonicity

        visited.add(key)

        # Check if all moves lead to opponent winning (i.e., they lose for us)
        all_moves_lead_to_opponent_win = True

        # Try increasing a (boxes)
        try:
            ways_a = (a + 1) ** b
            if ways_a < n:
                if not is_losing(a + 1, b):
                    all_moves_lead_to_opponent_win = False
        except OverflowError:
            pass

        # Try increasing b (items)
        try:
            ways_b = a ** (b + 1)
            if ways_b < n:
                if not is_losing(a, b + 1):
                    all_moves_lead_to_opponent_win = False
        except OverflowError:
            pass

        result = all_moves_lead_to_opponent_win
        memo[key] = result
        visited.discard(key)
        return result

    # With a >= 2, the game must end (a^b grows to n)
    if is_losing(a, b):
        return "Masha\n\n"
    else:
        return "Stas\n\n"

