    x = list(map(int, lines[1].split()))
    k_queries = list(map(int, lines[2].split()))

    LOG = max(1, n.bit_length())
    st_min = [[0] * n for _ in range(LOG)]
    st_max = [[0] * n for _ in range(LOG)]

    for i in range(n):
        st_min[0][i] = x[i]
        st_max[0][i] = x[i]

    for k in range(1, LOG):
            for i in range(n - (1 << k) + 1):
                st_min[k][i] = min(st_min[k-1][i], st_min[k-1][i + (1 << (k-1))])
                st_max[k][i] = max(st_max[k-1][i], st_max[k-1][i + (1 << (k-1))])

    def get_min(L, R):
        if L > R:
            return float('inf')
        length = R - L + 1
        k = length.bit_length() - 1
        if k < 0:
            k = 0
        return min(st_min[k][L], st_min[k][R - (1 << k) + 1])

    def get_max(L, R):
        if L > R:
            return float('-inf')
        length = R - L + 1
        k = length.bit_length() - 1
        if k < 0:
            k = 0
        return max(st_max[k][L], st_max[k][R - (1 << k) + 1])

    results = []
    for k in k_queries:
        threshold = w - k
        cuts = 0
        i = 0
        while i < n:
            cuts += 1
            if i == n - 1:
                break

            lo, hi = i, n - 1
            best = i
            while lo <= hi:
                mid = (lo + hi) // 2
                diff = get_max(i, mid) - get_min(i, mid)
                if diff <= threshold:
                    best = mid
                    lo = mid + 1
                else:
                    hi = mid - 1
            i = best + 1

        results.append(cuts)

    return '\n'.join(map(str, results))

