def solution(input_str):
    """
    Interactive problem solution: Navigate from (1,1) to 'F' on n×m board.
    Buttons L↔R or U↔D may be swapped. Returns sequence of moves.
    """
    input_str = input_str.strip()
    lines = input_str.split('\n')

    if not lines:
        return ""

    # Parse first line (may include swap flags)
    first_parts = lines[0].split()
    n = int(first_parts[0])
    m = int(first_parts[1])

    swapLR = int(first_parts[2]) if len(first_parts) > 2 else 0
    swapUD = int(first_parts[3]) if len(first_parts) > 3 else 0

    # Parse the game board
    grid = lines[1:n+1]

    # Find finish position
    finish_pos = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish_pos = (r, c)
                break
        if finish_pos:
            break

    if not finish_pos:
        return ""

    # Determine direction mappings based on swap flags
    if swapLR:
        moves = {'U': (0, -1), 'D': (0, 1), 'L': (1, 0), 'R': (-1, 0)}
    else:
        moves = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

    if swapUD:
        moves['U'], moves['D'] = moves['D'], moves['U']

    # BFS to find shortest path to finish
    start = (0, 0)
    queue = deque([(start, "")])
    visited = {start}

    while queue:
        (r, c), path = queue.popleft()

        if (r, c) == finish_pos:
            return path + "\n"

        for direction, (dr, dc) in moves.items():
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                if grid[nr][nc] != '*':
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append(((nr, nc), path + direction))

    return ""

